sys_script_include.script:
var InsuranceUtilsClient = Class.create();
InsuranceUtilsClient.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    type: 'InsuranceUtilsClient'
});var InsuranceUtilsClient = Class.create();
InsuranceUtilsClient.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    getInsuranceDetails: function () {
        var insurance = new GlideRecord('u_insurance');
        if (insurance.get(this.getParameter('sysparm_insurance_id'))) {
            return JSON.stringify({
                provider: insurance.getValue('u_provider'),
                policy_number: insurance.getValue('u_policy_number')
            });
        }
        return JSON.stringify({error: "Insurance not found"});
    }
});
